#include <fstream>
#include <iostream>

void solve(std::istream &in, std::ostream &out) {
    long long x, y; in >> x >> y;
    int answer = 0;
    for (int length = 3; length <= 17; ++length) {
        for (int repeated = 0; repeated <= 9; ++repeated) {
            for (int exceptional = 0; exceptional <= 9; ++exceptional) {
                if (exceptional == repeated) continue;
                for (int position = 0; position < length; ++position) {
                    const int leading = position == 0 ? exceptional : repeated;
                    if (leading == 0) continue;
                    long long number = 0;
                    for (int j = 0; j < length; ++j) {
                        number = number * 10 + (j == position ? exceptional : repeated);
                    }
                    if (x <= number && number <= y) ++answer;
                }
            }
        }
    }
    out << answer << '\n';
}

int main() {
    std::ifstream in("odometer.in");
    std::ofstream out("odometer.out");
    solve(in, out);
    return 0;
}
