#include <algorithm>
#include <fstream>
#include <iostream>
#include <utility>
#include <vector>

void solve(std::istream &in, std::ostream &out) {
    int n; in >> n;
    std::vector<std::pair<long long, char> > cows(n);
    for (int i = 0; i < n; ++i) in >> cows[i].first >> cows[i].second;
    std::sort(cows.begin(), cows.end());
    std::vector<int> earliest(2 * n + 1, -1);
    earliest[n] = 0;
    int balance = 0, runStart = 0;
    long long answer = 0;
    for (int i = 0; i < n; ++i) {
        if (i > 0 && cows[i].second != cows[i - 1].second) runStart = i;
        answer = std::max(answer, cows[i].first - cows[runStart].first);
        balance += cows[i].second == 'G' ? 1 : -1;
        const int first = earliest[balance + n];
        if (first != -1) answer = std::max(answer, cows[i].first - cows[first].first);
        else earliest[balance + n] = i + 1;
    }
    out << answer << '\n';
}

int main() {
    std::ifstream in("fairphoto.in");
    std::ofstream out("fairphoto.out");
    solve(in, out);
    return 0;
}
