#include <algorithm>
#include <fstream>
#include <iostream>
#include <queue>
#include <vector>

void solve(std::istream &in, std::ostream &out) {
    int n, m; in >> n >> m;
    std::vector<std::vector<int> > edges(n);
    for (int i = 0; i < m; ++i) {
        int a, b; in >> a >> b; --a; --b;
        edges[a].push_back(b); edges[b].push_back(a);
    }
    std::vector<int> color(n, -1);
    int answer = 0;
    for (int root = 0; root < n; ++root) {
        if (color[root] != -1) continue;
        std::queue<int> q;
        q.push(root); color[root] = 0;
        int count[2] = {1, 0};
        while (!q.empty()) {
            const int u = q.front(); q.pop();
            for (std::size_t i = 0; i < edges[u].size(); ++i) {
                const int v = edges[u][i];
                if (color[v] == -1) {
                    color[v] = 1 - color[u];
                    ++count[color[v]]; q.push(v);
                } else if (color[v] == color[u]) {
                    out << -1 << '\n'; return;
                }
            }
        }
        answer += std::max(count[0], count[1]);
    }
    out << answer << '\n';
}

int main() {
    std::ifstream in("decorate.in");
    std::ofstream out("decorate.out");
    solve(in, out);
    return 0;
}
